11: static bool validate_utf8(const char *b, size_t length) {
12:   const unsigned char *bytes = (const unsigned char *)b;
13:   const uint64_t high_bit_mask = UINT64_C(0x8080808080808080);
14:   size_t index = 0;
15: 
16:   while (index < length) {
17:     // Skip only complete, safely copied words containing exclusively ASCII bytes.
18:     while (length - index >= sizeof(uint64_t)) {
19:       uint64_t word;
20:       std::memcpy(&word, bytes + index, sizeof(word));
21:       if ((word & high_bit_mask) != 0) {
22:         break;
23:       }
24:       index += sizeof(word);
25:     }
26: 
27:     // A failed word test or the short tail is scanned to the next decoder input.
28:     while (index < length && bytes[index] < 0x80) {
29:       ++index;
30:     }
31:     if (index == length) {
32:       return true;
33:     }
34: 
35:     unsigned char byte1 = bytes[index++];
36:     if (byte1 < 0xE0) {
37:       // Two-byte form.
38:       if (index == length) {
39:         return false;
40:       }
41:       if (byte1 < 0xC2 || (bytes[index++] & 0xC0) != 0x80) {
42:         return false;
43:       }
44:     } else if (byte1 < 0xF0) {
45:       // Three-byte form.
46:       if (index + 1 >= length) {
47:         return false;
48:       }
49:       unsigned char byte2 = bytes[index++];
50:       if ((byte2 & 0xC0) != 0x80
51:           // Overlong? 5 most significant bits must not all be zero.
52:           || (byte1 == 0xE0 && byte2 < 0xA0)
53:           // Check for illegal surrogate codepoints.
54:           || (byte1 == 0xED && 0xA0 <= byte2)
55:           // Third byte trailing-byte test.
56:           || (bytes[index++] & 0xC0) != 0x80) {
57:         return false;
58:       }
59:     } else {
60:       // Four-byte form.
61:       if (index + 2 >= length) {
62:         return false;
63:       }
64:       int byte2 = bytes[index++];
65:       if ((byte2 & 0xC0) != 0x80
66:           // Check that 1 <= plane <= 16. Tricky optimized form of:
67:           // if (byte1 > (byte) 0xF4
68:           //     || byte1 == (byte) 0xF0 && byte2 < (byte) 0x90
69:           //     || byte1 == (byte) 0xF4 && byte2 > (byte) 0x8F)
70:           || (byte1 > 0xF4 || (byte1 == 0xF0 && byte2 < 0x90) || (byte1 == 0xF4 && byte2 > 0x8F))
71:           // Third byte trailing-byte test
72:           || (bytes[index++] & 0xC0) != 0x80
73:           // Fourth byte trailing-byte test
74:           || (bytes[index++] & 0xC0) != 0x80) {
75:         return false;
76:       }
77:     }
78:   }
79:   return true;
80: }
