80: static inline bool classify_avx2_block(const unsigned char *bytes,
81:                                        size_t index,
82:                                        const Avx2Constants *constants,
83:                                        Avx2Masks *masks) {
84:   const __m256i value =
85:       _mm256_loadu_si256((const __m256i *)(bytes + index));
86:   const __m256i next =
87:       _mm256_loadu_si256((const __m256i *)(bytes + index + 1));
88:   const __m256i high_order = _mm256_xor_si256(value, constants->high_bit);
89:   const __m256i next_order = _mm256_xor_si256(next, constants->high_bit);
90: 
91:   const uint32_t ascii =
92:       ~static_cast<uint32_t>(_mm256_movemask_epi8(value));
93:   const __m256i continuation_bytes = _mm256_cmpeq_epi8(
94:       _mm256_and_si256(value, constants->mask_c0), constants->cont_value);
95:   masks->continuation =
96:       static_cast<uint32_t>(_mm256_movemask_epi8(continuation_bytes));
97: 
98:   const __m256i two_pattern = _mm256_cmpeq_epi8(
99:       _mm256_and_si256(value, constants->mask_e0), constants->c0);
100:   const __m256i is_c0 = _mm256_cmpeq_epi8(value, constants->c0);
101:   const __m256i is_c1 = _mm256_cmpeq_epi8(value, constants->c1);
102:   masks->lead2 = static_cast<uint32_t>(_mm256_movemask_epi8(
103:       _mm256_andnot_si256(_mm256_or_si256(is_c0, is_c1), two_pattern)));
104: 
105:   const __m256i three_pattern = _mm256_cmpeq_epi8(
106:       _mm256_and_si256(value, constants->mask_f0), constants->mask_e0);
107:   masks->lead3 =
108:       static_cast<uint32_t>(_mm256_movemask_epi8(three_pattern));
109: 
110:   const __m256i at_least_f0 =
111:       _mm256_cmpgt_epi8(high_order, constants->unsigned_order_min);
112:   const __m256i below_f5 =
113:       _mm256_cmpgt_epi8(constants->unsigned_order_max_plus_one, high_order);
114:   masks->lead4 = static_cast<uint32_t>(_mm256_movemask_epi8(
115:       _mm256_and_si256(at_least_f0, below_f5)));
116: 
117:   if ((ascii | masks->continuation | masks->lead2 | masks->lead3 |
118:        masks->lead4) != UINT32_MAX) {
119:     return false;
120:   }
