122:   const __m256i e0 = _mm256_cmpeq_epi8(value, _mm256_set1_epi8(-32));
123:   const __m256i ed = _mm256_cmpeq_epi8(value, _mm256_set1_epi8(-19));
124:   const __m256i f0 = _mm256_cmpeq_epi8(value, _mm256_set1_epi8(-16));
125:   const __m256i f4 = _mm256_cmpeq_epi8(value, _mm256_set1_epi8(-12));
126:   const __m256i bad_e0 = _mm256_and_si256(
127:       e0, _mm256_cmpgt_epi8(constants->order_20, next_order));
128:   const __m256i bad_ed = _mm256_and_si256(
129:       ed, _mm256_cmpgt_epi8(next_order, constants->order_1f));
130:   const __m256i bad_f0 = _mm256_and_si256(
131:       f0, _mm256_cmpgt_epi8(constants->order_10, next_order));
132:   const __m256i bad_f4 = _mm256_and_si256(
133:       f4, _mm256_cmpgt_epi8(next_order, constants->order_0f));
134:   const __m256i special_bad = _mm256_or_si256(
135:       _mm256_or_si256(bad_e0, bad_ed), _mm256_or_si256(bad_f0, bad_f4));
136:   return _mm256_movemask_epi8(special_bad) == 0;
