11: static bool validate_scalar_tail(const unsigned char *bytes, size_t length,
12:                                  size_t index, unsigned pending) {
13:   while (index < length) {
14:     unsigned char byte = bytes[index];
15:     if (pending != 0) {
16:       if ((byte & 0xC0) != 0x80) {
17:         return false;
18:       }
19:       --pending;
20:       ++index;
21:       continue;
22:     }
23: 
24:     if (byte < 0x80) {
25:       ++index;
26:     } else if (byte < 0xE0) {
27:       if (length - index < 2 || byte < 0xC2 || byte > 0xDF ||
28:           (bytes[index + 1] & 0xC0) != 0x80) {
29:         return false;
30:       }
31:       index += 2;
32:     } else if (byte < 0xF0) {
33:       if (length - index < 3 ||
34:           (bytes[index + 1] & 0xC0) != 0x80 ||
35:           (byte == 0xE0 && bytes[index + 1] < 0xA0) ||
36:           (byte == 0xED && bytes[index + 1] >= 0xA0) ||
37:           (bytes[index + 2] & 0xC0) != 0x80) {
38:         return false;
39:       }
40:       index += 3;
41:     } else {
42:       if (length - index < 4 || byte > 0xF4 ||
43:           (bytes[index + 1] & 0xC0) != 0x80 ||
44:           (byte == 0xF0 && bytes[index + 1] < 0x90) ||
45:           (byte == 0xF4 && bytes[index + 1] > 0x8F) ||
