34:           (bytes[index + 1] & 0xC0) != 0x80 ||
35:           (byte == 0xE0 && bytes[index + 1] < 0xA0) ||
36:           (byte == 0xED && bytes[index + 1] >= 0xA0) ||
37:           (bytes[index + 2] & 0xC0) != 0x80) {
38:         return false;
39:       }
40:       index += 3;
